@startuml

class Customer {
  + name : string
  + phoneNumber : string
}

class Table {
  + seatCount : int
  + isSmoking : boolean
}

class Reservation {
  + reservationDate : date
  + reservationTime : time
  + numberOfPeople : int
}

class Waiter {
  + name : string
  + yearsOfService : int
}

class Bill {
  + totalAmount : double
}

class Dish {
  + name : string
  + unitPrice : double
}

Customer "1" -- "0..*" Reservation
Reservation "1" -- "1..*" Table
Customer "1" -- "0..*" Bill
Waiter "1" -- "0..*" Bill
Bill "1" *-- "1..*" Dish

@enduml

